import React, { useState, useEffect, useCallback } from 'react';
import { Form, Input, message, Modal, Select, Table, DatePicker, Popconfirm } from 'antd';
import { UnorderedListOutlined, AreaChartOutlined, EditOutlined, DeleteOutlined } from '@ant-design/icons';
import Layout from '../components/Layout/Layout';
import axios from 'axios';
import Spinner from '../components/spinner';
import moment from 'moment';
import Analytics from '../components/Analytics';

const { RangePicker } = DatePicker;

const HomePage = () => {
  const [showModal, setShowModal] = useState(false);
  const [loading, setLoading] = useState(false);
  const [allTransactions, setAllTransactions] = useState([]);
  const [frequency, setFrequency] = useState('7');
  const [selectedDate, setSelectedDate] = useState([]);
  const [type, setType] = useState('all');
  const [viewData, setViewData] = useState('table');
  const [editable, setEditable] = useState(null);

  const [form] = Form.useForm();

  // Populate or reset form fields
  useEffect(() => {
    if (editable) {
      form.setFieldsValue({
        ...editable,
        date: editable.date ? moment(editable.date).format('YYYY-MM-DD') : '',
      });
    } else {
      form.resetFields();
    }
  }, [editable, form]);

  // Fetch transactions handler
  const getAllTransactions = useCallback(async () => {
    try {
      const storedUser = localStorage.getItem('user');
      if (!storedUser) return;

      const user = JSON.parse(storedUser);
      if (!user?._id) return;

      setLoading(true);

      const formattedSelectedDate =
        frequency === 'custom' && selectedDate?.length === 2
          ? [moment(selectedDate[0]).toISOString(), moment(selectedDate[1]).toISOString()]
          : [];

      const res = await axios.post('/api/v1/transactions/get-transaction', {
        userId: user._id,
        frequency,
        selectedDate: formattedSelectedDate,
        type,
      });

      setLoading(false);
      setAllTransactions(res.data || []);
    } catch (error) {
      setLoading(false);
      console.error(error);
      message.error('Failed to fetch transactions');
    }
  }, [frequency, selectedDate, type]);

  useEffect(() => {
    getAllTransactions();
  }, [getAllTransactions]);

  // Delete transaction
  const handleDelete = async (record) => {
    try {
      setLoading(true);
      await axios.post('/api/v1/transactions/delete-transaction', {
        transactionId: record._id,
      });
      setLoading(false);
      message.success('Transaction deleted successfully');
      getAllTransactions();
    } catch (error) {
      setLoading(false);
      console.error(error);
      message.error('Failed to delete transaction');
    }
  };

  // Submit add / edit transaction
  const handleSubmit = async (values) => {
    try {
      const storedUser = localStorage.getItem('user');
      const user = storedUser ? JSON.parse(storedUser) : null;

      if (!user?._id) {
        message.error('User not authenticated');
        return;
      }

      setLoading(true);

      const payloadData = {
        ...values,
        amount: Number(values.amount),
        userId: user._id,
      };

      if (editable) {
        await axios.post('/api/v1/transactions/edit-transaction', {
          payload: payloadData,
          transactionId: editable._id,
        });
        message.success('Transaction updated successfully');
      } else {
        await axios.post('/api/v1/transactions/add-transaction', payloadData);
        message.success('Transaction added successfully');
      }

      setLoading(false);
      setShowModal(false);
      setEditable(null);
      form.resetFields();
      getAllTransactions();
    } catch (error) {
      setLoading(false);
      console.error(error);
      message.error('Transaction operation failed');
    }
  };

  const columns = [
    {
      title: 'Date',
      dataIndex: 'date',
      render: (text) => <span>{moment(text).format('DD-MM-YYYY')}</span>,
    },
    {
      title: 'Amount',
      dataIndex: 'amount',
      render: (text) => <span>₹{text}</span>,
    },
    {
      title: 'Type',
      dataIndex: 'type',
      render: (text) => <span className={`text-capitalize ${text === 'income' ? 'text-success' : 'text-danger'}`}>{text}</span>,
    },
    {
      title: 'Category',
      dataIndex: 'category',
      render: (text) => <span className="text-capitalize">{text}</span>,
    },
    {
      title: 'Reference',
      dataIndex: 'reference',
    },
    {
      title: 'Action',
      render: (_, record) => (
        <div>
          <EditOutlined
            className="mx-2 text-primary"
            style={{ cursor: 'pointer' }}
            onClick={() => {
              setEditable(record);
              setShowModal(true);
            }}
          />
          <Popconfirm
            title="Are you sure you want to delete this transaction?"
            onConfirm={() => handleDelete(record)}
            okText="Yes"
            cancelText="No"
          >
            <DeleteOutlined className="mx-2 " onClick={() =>{ handleDelete(record);

             }} />
          </Popconfirm>
        </div>
      ),
    },
  ];

  return (
    <Layout>
      {loading && <Spinner />}
      <div className="filters d-flex justify-content-between align-items-center p-3 border-bottom">
        <div>
          <h6>Select Frequency</h6>
          <Select value={frequency} onChange={(val) => setFrequency(val)} style={{ width: 140 }}>
            <Select.Option value="7">Last Week</Select.Option>
            <Select.Option value="30">Last Month</Select.Option>
            <Select.Option value="365">Last 1 Year</Select.Option>
            <Select.Option value="custom">Custom</Select.Option>
          </Select>
          {frequency === 'custom' && (
            <RangePicker
              className="mx-2"
              value={selectedDate}
              onChange={(val) => setSelectedDate(val)}
            />
          )}
        </div>

        <div>
          <h6>Select Type</h6>
          <Select value={type} onChange={(val) => setType(val)} style={{ width: 120 }}>
            <Select.Option value="all">All</Select.Option>
            <Select.Option value="income">Income</Select.Option>
            <Select.Option value="expense">Expense</Select.Option>
          </Select>
        </div>

        <div className="switch-icons">
          <UnorderedListOutlined
            className={`mx-2 ${viewData === 'table' ? 'active-icon' : 'inactive-icon'}`}
            style={{ fontSize: '18px', cursor: 'pointer' }}
            onClick={() => setViewData('table')}
          />
          <AreaChartOutlined
            className={`mx-2 ${viewData === 'analytics' ? 'active-icon' : 'inactive-icon'}`}
            style={{ fontSize: '18px', cursor: 'pointer' }}
            onClick={() => setViewData('analytics')}
          />
        </div>

        <div>
          <button
            className="btn btn-primary"
            onClick={() => {
              setEditable(null);
              setShowModal(true);
            }}
          >
            Add New
          </button>
        </div>
      </div>

      <div className="content p-3">
        {viewData === 'table' ? (
          <Table rowKey="_id" columns={columns} dataSource={allTransactions} pagination={{ pageSize: 8 }} />
        ) : (
          <Analytics allTransactions={allTransactions} />
        )}
      </div>

      <Modal
        title={editable ? 'Edit Transaction' : 'Add Transaction'}
        open={showModal}
        destroyOnClose
        onCancel={() => {
          setShowModal(false);
          setEditable(null);
          form.resetFields();
        }}
        footer={null}
      >
        <Form form={form} layout="vertical" onFinish={handleSubmit}>
          <Form.Item label="Amount" name="amount" rules={[{ required: true, message: 'Amount is required' }]}>
            <Input type="number" placeholder="Enter amount" />
          </Form.Item>

          <Form.Item label="Type" name="type" rules={[{ required: true, message: 'Type is required' }]}>
            <Select placeholder="Select type">
              <Select.Option value="income">Income</Select.Option>
              <Select.Option value="expense">Expense</Select.Option>
            </Select>
          </Form.Item>

          <Form.Item label="Category" name="category" rules={[{ required: true, message: 'Category is required' }]}>
            <Select placeholder="Select category">
              <Select.Option value="salary">Salary</Select.Option>
              <Select.Option value="tip">Tip</Select.Option>
              <Select.Option value="project">Project</Select.Option>
              <Select.Option value="food">Food</Select.Option>
              <Select.Option value="movie">Movie</Select.Option>
              <Select.Option value="bills">Bills</Select.Option>
              <Select.Option value="medical">Medical</Select.Option>
              <Select.Option value="fee">Fee</Select.Option>
              <Select.Option value="tax">Tax</Select.Option>
            </Select>
          </Form.Item>

          <Form.Item label="Date" name="date" rules={[{ required: true, message: 'Date is required' }]}>
            <Input type="date" />
          </Form.Item>

          <Form.Item label="Reference" name="reference">
            <Input placeholder="Reference (optional)" />
          </Form.Item>

          <Form.Item label="Description" name="description">
            <Input placeholder="Description (optional)" />
          </Form.Item>

          <div className="d-flex justify-content-end">
            <button type="submit" className="btn btn-primary">
              Save
            </button>
          </div>
        </Form>
      </Modal>
    </Layout>
  );
};

export default HomePage;