
import React from "react";
import { Progress } from "antd";

const Analytics = ({ allTransactions = [] }) => {
  // Categories
  const categories = [
    "salary",
    "tip",
    "project",
    "food",
    "movie",
    "bills",
    "medical",
    "fee",
    "tax",
  ];

  // Total Transactions
  const totalTransactions = allTransactions.length;

  const totalIncomeTransactions = allTransactions.filter(
    (transaction) => transaction.type === "income"
  );

  const totalExpenseTransactions = allTransactions.filter(
    (transaction) => transaction.type === "expense"
  );

  const totalIncomePercent = totalTransactions
    ? (totalIncomeTransactions.length / totalTransactions) * 100
    : 0;

  const totalExpensePercent = totalTransactions
    ? (totalExpenseTransactions.length / totalTransactions) * 100
    : 0;

  // Total Turnover
  const totalTurnover = allTransactions.reduce(
    (acc, transaction) => acc + Number(transaction.amount || 0),
    0
  );

  const totalIncomeTurnover = allTransactions
    .filter((transaction) => transaction.type === "income")
    .reduce(
      (acc, transaction) => acc + Number(transaction.amount || 0),
      0
    );

  const totalExpenseTurnover = allTransactions
    .filter((transaction) => transaction.type === "expense")
    .reduce(
      (acc, transaction) => acc + Number(transaction.amount || 0),
      0
    );

  const totalIncomeTurnoverPercent = totalTurnover
    ? (totalIncomeTurnover / totalTurnover) * 100
    : 0;

  const totalExpenseTurnoverPercent = totalTurnover
    ? (totalExpenseTurnover / totalTurnover) * 100
    : 0;

  return (
    <>
      {/* Transaction Count and Turnover */}
      <div className="row m-3">
        {/* Transaction Count Card */}
        <div className="col-md-4">
          <div className="card">
            <div className="card-header">
              <h4>Total Transactions: {totalTransactions}</h4>
            </div>

            <div className="card-body">
              <h5 className="text-success">
                Income: {totalIncomeTransactions.length}
              </h5>

              <h5 className="text-danger">
                Expense: {totalExpenseTransactions.length}
              </h5>

              <div className="d-flex justify-content-center mt-3">
                <Progress
                  type="circle"
                  strokeColor="green"
                  className="mx-2"
                  percent={Number(totalIncomePercent.toFixed(0))}
                />

                <Progress
                  type="circle"
                  strokeColor="red"
                  className="mx-2"
                  percent={Number(totalExpensePercent.toFixed(0))}
                />
              </div>
            </div>
          </div>
        </div>

        {/* Turnover Card */}
        <div className="col-md-4">
          <div className="card">
            <div className="card-header">
              <h4>Total Turnover: {totalTurnover}</h4>
            </div>

            <div className="card-body">
              <h5 className="text-success">
                Income: {totalIncomeTurnover}
              </h5>

              <h5 className="text-danger">
                Expense: {totalExpenseTurnover}
              </h5>

              <div className="d-flex justify-content-center mt-3">
                <Progress
                  type="circle"
                  strokeColor="green"
                  className="mx-2"
                  percent={Number(
                    totalIncomeTurnoverPercent.toFixed(0)
                  )}
                />

                <Progress
                  type="circle"
                  strokeColor="red"
                  className="mx-2"
                  percent={Number(
                    totalExpenseTurnoverPercent.toFixed(0)
                  )}
                />
              </div>
            </div>
          </div>
        </div>
      </div>

      {/* Category Wise */}
      <div className="row m-3">
        {/* Category-wise Income */}
        <div className="col-md-5">
          <h4>Category-wise Income</h4>

          {categories.map((category) => {
            const amount = allTransactions
              .filter(
                (transaction) =>
                  transaction.type === "income" &&
                  transaction.category === category
              )
              .reduce(
                (acc, transaction) =>
                  acc + Number(transaction.amount || 0),
                0
              );

            return (
              amount > 0 && (
                <div className="card mb-3" key={category}>
                  <div className="card-body">
                    <h5>{category}</h5>

                    <Progress
                      percent={Number(
                        (
                          (amount / totalIncomeTurnover) *
                          100
                        ).toFixed(0)
                      )}
                      strokeColor="green"
                    />
                  </div>
                </div>
              )
            );
          })}
        </div>

        {/* Category-wise Expense */}
        <div className="col-md-5">
          <h4>Category-wise Expense</h4>

          {categories.map((category) => {
            const amount = allTransactions
              .filter(
                (transaction) =>
                  transaction.type === "expense" &&
                  transaction.category === category
              )
              .reduce(
                (acc, transaction) =>
                  acc + Number(transaction.amount || 0),
                0
              );

            return (
              amount > 0 && (
                <div className="card mb-3" key={category}>
                  <div className="card-body">
                    <h5>{category}</h5>

                    <Progress
                      percent={Number(
                        (
                          (amount / totalExpenseTurnover) *
                          100
                        ).toFixed(0)
                      )}
                      strokeColor="red"
                    />
                  </div>
                </div>
              )
            );
          })}
        </div>
      </div>
    </>
  );
};

export default Analytics;

